CREATE DATABASE IF NOT EXISTS talenthub;
USE talenthub;
CREATE TABLE students (id INT AUTO_INCREMENT PRIMARY KEY, usn VARCHAR(30) NOT NULL UNIQUE, full_name VARCHAR(120) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, branch ENUM('CSE','ECE','ISE','MECH','CIVIL') NOT NULL, cgpa DECIMAL(4,2) NOT NULL, active_backlogs INT NOT NULL DEFAULT 0, cleared_backlogs INT NOT NULL DEFAULT 0, has_accepted_offer BOOLEAN NOT NULL DEFAULT FALSE, INDEX idx_students_branch(branch));
CREATE TABLE companies (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL);
CREATE TABLE job_listings (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, role VARCHAR(150) NOT NULL, season VARCHAR(30) NOT NULL, min_cgpa DECIMAL(4,2) NOT NULL, max_backlogs INT NOT NULL DEFAULT 0, drive_date DATE NOT NULL, is_open BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT fk_job_company FOREIGN KEY(company_id) REFERENCES companies(id), INDEX idx_jobs_open_date(is_open,drive_date));
CREATE TABLE job_allowed_branches (job_id INT NOT NULL, branch ENUM('CSE','ECE','ISE','MECH','CIVIL') NOT NULL, PRIMARY KEY(job_id,branch), CONSTRAINT fk_allowed_job FOREIGN KEY(job_id) REFERENCES job_listings(id) ON DELETE CASCADE);
CREATE TABLE applications (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, job_id INT NOT NULL, status ENUM('APPLIED','SHORTLISTED','INTERVIEW_SCHEDULED','INTERVIEWED','OFFERED','ACCEPTED') NOT NULL DEFAULT 'APPLIED', applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(student_id,job_id), CONSTRAINT fk_application_student FOREIGN KEY(student_id) REFERENCES students(id), CONSTRAINT fk_application_job FOREIGN KEY(job_id) REFERENCES job_listings(id), INDEX idx_app_status(status));
CREATE TABLE interview_slots (id INT AUTO_INCREMENT PRIMARY KEY, application_id INT NOT NULL, round_no INT NOT NULL, scheduled_at DATETIME NOT NULL, venue VARCHAR(150) NOT NULL, passed BOOLEAN NULL, notes TEXT NULL, UNIQUE(application_id,round_no), CONSTRAINT fk_interview_application FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE offers (id INT AUTO_INCREMENT PRIMARY KEY, application_id INT NOT NULL UNIQUE, package_lpa DECIMAL(5,2) NOT NULL, offer_letter_key VARCHAR(255) NOT NULL, accepted BOOLEAN NOT NULL DEFAULT FALSE, CONSTRAINT fk_offer_application FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('STUDENT','ADMIN') NOT NULL, student_id INT NULL UNIQUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_user_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, CONSTRAINT chk_user_role_link CHECK ((role='STUDENT' AND student_id IS NOT NULL) OR (role='ADMIN' AND student_id IS NULL)));
